/**
 * SNIPPET À AJOUTER dans generate-static-pages.mjs
  *
   * Coller ces fonctions AVANT la fonction principale,
    * puis appeler generateHeadHTML(article) dans le template HTML.
     *
      * Lovable : "Ajoute ces fonctions dans generate-static-pages.mjs
       * et utilise generateHeadHTML(article) pour remplacer les balises
        * <head> actuellement générées."
         */

         // ─── 1. FONCTION PRINCIPALE — génère tout le <head> d'un article ────────────

         function generateHeadHTML(article) {
           const siteUrl   = 'https://www.jemassuremoinscher.fr'
             const canonical = `${siteUrl}/blog/${article.slug}`
               const ogImage   = article.image_url || `${siteUrl}/og/blog-default.jpg`

                 // Extraire les FAQ de l'article si elles existent
                   // Format attendu dans Supabase : colonne "faqs" = JSON array [{question, answer}]
                     const faqs = article.faqs || extractFAQsFromMarkdown(article.content)

                       return `
                         <!-- ═══ SEO ESSENTIALS ═══════════════════════════════════════════════ -->
                           <title>${escapeHtml(article.title)} | jemassuremoinscher.fr</title>
                             <meta name="description"    content="${escapeHtml(article.meta_description || article.excerpt || article.title)}" />
                               <link rel="canonical"       href="${canonical}" />
                                 <meta name="robots"         content="index, follow, max-snippet:-1, max-image-preview:large" />

                                   <!-- ═══ OPEN GRAPH (Facebook, LinkedIn, WhatsApp) ════════════════════ -->
                                     <meta property="og:type"        content="article" />
                                       <meta property="og:url"         content="${canonical}" />
                                         <meta property="og:title"       content="${escapeHtml(article.title)}" />
                                           <meta property="og:description" content="${escapeHtml(article.excerpt || article.meta_description || '')}" />
                                             <meta property="og:image"       content="${ogImage}" />
                                               <meta property="og:image:width" content="1200" />
                                                 <meta property="og:image:height"content="630" />
                                                   <meta property="og:locale"      content="fr_FR" />
                                                     <meta property="og:site_name"   content="jemassuremoinscher.fr" />
                                                       <meta property="article:published_time" content="${article.published_at}" />
                                                         <meta property="article:modified_time"  content="${article.updated_at || article.published_at}" />
                                                           <meta property="article:author"         content="${escapeHtml(article.author_name || 'Équipe jemassuremoinscher.fr')}" />
                                                             <meta property="article:section"        content="Assurance" />

                                                               <!-- ═══ TWITTER / X CARDS ════════════════════════════════════════════ -->
                                                                 <meta name="twitter:card"        content="summary_large_image" />
                                                                   <meta name="twitter:title"       content="${escapeHtml(article.title)}" />
                                                                     <meta name="twitter:description" content="${escapeHtml(article.excerpt || '')}" />
                                                                       <meta name="twitter:image"       content="${ogImage}" />

                                                                         <!-- ═══ SCHEMA.ORG — Article (E-E-A-T + GEO) ════════════════════════ -->
                                                                           <script type="application/ld+json">
                                                                             ${generateArticleSchema(article, siteUrl, canonical, ogImage)}
                                                                               </script>

                                                                                 <!-- ═══ SCHEMA.ORG — BreadcrumbList ════════════════════════════════= -->
                                                                                   <script type="application/ld+json">
                                                                                     ${generateBreadcrumbSchema(article, siteUrl, canonical)}
                                                                                       </script>

                                                                                         ${faqs.length > 0 ? `
                                                                                           <!-- ═══ SCHEMA.ORG — FAQPage (Featured Snippets + GEO) ══════════════ -->
                                                                                             <script type="application/ld+json">
                                                                                               ${generateFAQSchema(faqs)}
                                                                                                 </script>
                                                                                                   ` : ''}
                                                                                                     `
                                                                                                     }
                                                                                                     
                                                                                                     // ─── 2. SCHEMA ARTICLE ──────────────────────────────────────────────────────
                                                                                                     
                                                                                                     function generateArticleSchema(article, siteUrl, canonical, ogImage) {
                                                                                                       return JSON.stringify({
                                                                                                           '@context': 'https://schema.org',
                                                                                                               '@type': 'Article',
                                                                                                                   headline:     article.title,
                                                                                                                       description:  article.excerpt || article.meta_description || '',
                                                                                                                           url:          canonical,
                                                                                                                               image:        ogImage,
                                                                                                                                   datePublished: article.published_at,
                                                                                                                                       dateModified:  article.updated_at || article.published_at,  // ← Signal fraîcheur IA
                                                                                                                                           author: {
                                                                                                                                                 '@type':    'Person',
                                                                                                                                                       name:       article.author_name || 'Équipe jemassuremoinscher.fr',
                                                                                                                                                             jobTitle:   'Conseiller en assurances certifié ORIAS',
                                                                                                                                                                   worksFor: {
                                                                                                                                                                           '@type': 'Organization',
                                                                                                                                                                                   name:    'jemassuremoinscher.fr',
                                                                                                                                                                                           url:     siteUrl,
                                                                                                                                                                                                 },
                                                                                                                                                                                                     },
                                                                                                                                                                                                         publisher: {
                                                                                                                                                                                                               '@type': 'Organization',
                                                                                                                                                                                                                     name:    'jemassuremoinscher.fr',
                                                                                                                                                                                                                           url:     siteUrl,
                                                                                                                                                                                                                                 logo: {
                                                                                                                                                                                                                                         '@type': 'ImageObject',
                                                                                                                                                                                                                                                 url:     `${siteUrl}/logo.svg`,
                                                                                                                                                                                                                                                       },
                                                                                                                                                                                                                                                           },
                                                                                                                                                                                                                                                               mainEntityOfPage: {
                                                                                                                                                                                                                                                                     '@type': 'WebPage',
                                                                                                                                                                                                                                                                           '@id':   canonical,
                                                                                                                                                                                                                                                                               },
                                                                                                                                                                                                                                                                                   // Catégorie et tags pour le contexte IA
                                                                                                                                                                                                                                                                                       articleSection: article.category || 'Assurance',
                                                                                                                                                                                                                                                                                           keywords:       Array.isArray(article.tags) ? article.tags.join(', ') : (article.tags || ''),
                                                                                                                                                                                                                                                                                               inLanguage:     'fr-FR',
                                                                                                                                                                                                                                                                                                   isAccessibleForFree: true,
                                                                                                                                                                                                                                                                                                     }, null, 2)
                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                     // ─── 3. SCHEMA BREADCRUMB ────────────────────────────────────────────────────
                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                     function generateBreadcrumbSchema(article, siteUrl, canonical) {
                                                                                                                                                                                                                                                                                                       return JSON.stringify({
                                                                                                                                                                                                                                                                                                           '@context': 'https://schema.org',
                                                                                                                                                                                                                                                                                                               '@type':    'BreadcrumbList',
                                                                                                                                                                                                                                                                                                                   itemListElement: [
                                                                                                                                                                                                                                                                                                                         {
                                                                                                                                                                                                                                                                                                                                 '@type':    'ListItem',
                                                                                                                                                                                                                                                                                                                                         position:   1,
                                                                                                                                                                                                                                                                                                                                                 name:       'Accueil',
                                                                                                                                                                                                                                                                                                                                                         item:       siteUrl,
                                                                                                                                                                                                                                                                                                                                                               },
                                                                                                                                                                                                                                                                                                                                                                     {
                                                                                                                                                                                                                                                                                                                                                                             '@type':    'ListItem',
                                                                                                                                                                                                                                                                                                                                                                                     position:   2,
                                                                                                                                                                                                                                                                                                                                                                                             name:       'Blog',
                                                                                                                                                                                                                                                                                                                                                                                                     item:       `${siteUrl}/blog`,
                                                                                                                                                                                                                                                                                                                                                                                                           },
                                                                                                                                                                                                                                                                                                                                                                                                                 {
                                                                                                                                                                                                                                                                                                                                                                                                                         '@type':    'ListItem',
                                                                                                                                                                                                                                                                                                                                                                                                                                 position:   3,
                                                                                                                                                                                                                                                                                                                                                                                                                                         name:       article.title,
                                                                                                                                                                                                                                                                                                                                                                                                                                                 item:       canonical,
                                                                                                                                                                                                                                                                                                                                                                                                                                                       },
                                                                                                                                                                                                                                                                                                                                                                                                                                                           ],
                                                                                                                                                                                                                                                                                                                                                                                                                                                             }, null, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                             // ─── 4. SCHEMA FAQPAGE ──────────────────────────────────────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                             function generateFAQSchema(faqs) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                               return JSON.stringify({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                   '@context':   'https://schema.org',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                       '@type':      'FAQPage',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                           mainEntity:   faqs.map(faq => ({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 '@type': 'Question',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       name:    faq.question,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             acceptedAnswer: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     '@type': 'Answer',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             text:    faq.answer,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       })),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }, null, 2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // ─── 5. EXTRACTION FAQ AUTOMATIQUE depuis le markdown ───────────────────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // Si tes articles ont des sections H2/H3 "Questions fréquentes" avec des Q/R,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // cette fonction les extrait automatiquement.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         // Format attendu dans le markdown :
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         //   ### Question ?
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         //   Réponse complète...
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         function extractFAQsFromMarkdown(markdown) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           if (!markdown) return []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             const faqs = []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               // Cherche les patterns H3 suivis de paragraphes (format Q/R classique)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 const faqSectionMatch = markdown.match(/#{2,3}\s*questions?\s*fr[ée]quentes?[\s\S]*$/i)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (!faqSectionMatch) return []
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     const faqSection  = faqSectionMatch[0]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       const questionReg = /###?\s+(.+\?)\s*\n+([\s\S]+?)(?=###?|\n#{1,2}\s|$)/gi
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         let match
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           while ((match = questionReg.exec(faqSection)) !== null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const question = match[1].trim()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   const answer   = match[2].trim().replace(/\*\*/g, '').replace(/\*/g, '').substring(0, 500)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (question && answer && answer.length > 50) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             faqs.push({ question, answer })
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     return faqs.slice(0, 10) // Max 10 FAQ par page
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     // ─── 6. UTILITAIRE — Échapper les caractères HTML dans les attributs ─────────
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     function escapeHtml(str) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       if (!str) return ''
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         return String(str)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .replace(/&/g, '&amp;')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 .replace(/"/g, '&quot;')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     .replace(/'/g, '&#39;')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         .replace(/</g, '&lt;')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             .replace(/>/g, '&gt;')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             }
